def containsNearbyDuplicate(nums, k):
    window = set()
    for i, num in enumerate(nums):
        if num in window:
            return True
        window.add(num)
        if len(window) > k:
            window.remove(nums[i - k])
    return False

def numOfSubarrays(arr, k, threshold):
    window_sum = sum(arr[:k])
    count = 1 if window_sum >= k * threshold else 0
    for i in range(k, len(arr)):
        window_sum += arr[i] - arr[i - k]
        if window_sum >= k * threshold:
            count += 1
    return count

def findMaxConsecutiveOnes(nums):
    max_count = curr = 0
    for n in nums:
        curr = curr + 1 if n == 1 else 0
        max_count = max(max_count, curr)
    return max_count

def maxProduct(nums):
    first = second = 0
    for n in nums:
        if n >= first:
            second = first
            first = n
        elif n > second:
            second = n
    return (first - 1) * (second - 1)

def longestOnes(nums, k):
    left = zeros = max_len = 0
    for right in range(len(nums)):
        if nums[right] == 0:
            zeros += 1
        while zeros > k:
            if nums[left] == 0:
                zeros -= 1
            left += 1
        max_len = max(max_len, right - left + 1)
    return max_len

def numSubarrayProductLessThanK(nums, k):
    if k <= 1:
        return 0
    product = 1
    left = count = 0
    for right in range(len(nums)):
        product *= nums[right]
        while product >= k:
            product //= nums[left]
            left += 1
        count += right - left + 1
    return count

def findLengthOfLCIS(nums):
    if not nums:
        return 0
    max_len = curr = 1
    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            curr += 1
            max_len = max(max_len, curr)
        else:
            curr = 1
    return max_len

def longestKReplacement(s, k):
    freq = {}
    left = max_freq = result = 0
    for right in range(len(s)):
        freq[s[right]] = freq.get(s[right], 0) + 1
        max_freq = max(max_freq, freq[s[right]])
        # window is invalid when replacements needed > k
        if (right - left + 1) - max_freq > k:
            freq[s[left]] -= 1
            left += 1
        result = max(result, right - left + 1)
    return result

def maxSatisfied(customers, grumpy, k):
    # base: always satisfied
    base = sum(c for c, g in zip(customers, grumpy) if g == 0)
    # sliding window: extra satisfied during technique window
    extra = window = 0
    for i in range(len(customers)):
        if grumpy[i] == 1:
            window += customers[i]
        if i >= k and grumpy[i - k] == 1:
            window -= customers[i - k]
        extra = max(extra, window)
    return base + extra

