def maximumSubarraySum(nums, k):
    freq = defaultdict(int)
    window_sum = 0
    max_sum = 0

    for i in range(len(nums)):
        freq[nums[i]] += 1
        window_sum += nums[i]
        if i >= k:
            freq[nums[i - k]] -= 1
            if freq[nums[i - k]] == 0:
                del freq[nums[i - k]]
            window_sum -= nums[i - k]
        if i >= k - 1 and len(freq) == k:
            max_sum = max(max_sum, window_sum)
    return max_sum

def findLength(nums1, nums2):
    m, n = len(nums1), len(nums2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    result = 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if nums1[i-1] == nums2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
                result = max(result, dp[i][j])
    return result

from collections import Counter

def equalCountSubstrings(s, count):
    result = 0
    for num_unique in range(1, 27):
        k = num_unique * count
        if k > len(s):
            break
        window = Counter(s[:k])
        if len(window) == num_unique and all(v == count for v in window.values()):
            result += 1
        for i in range(k, len(s)):
            window[s[i]] += 1
            window[s[i-k]] -= 1
            if window[s[i-k]] == 0:
                del window[s[i-k]]
            if len(window) == num_unique and all(v == count for v in window.values()):
                result += 1
    return result

