        sub = int(s[i:i+k])
        if sub != 0 and num % sub == 0:
            count += 1
    return count

def decrypt(code, k):
    n = len(code)
    result = [0] * n
    if k == 0:
        return result
    doubled = code + code
    for i in range(n):
        if k > 0:
            result[i] = sum(doubled[i+1:i+1+k])
        else:
            result[i] = sum(doubled[i-abs(k)+n:i+n])
    return result

def longestContinuousSubstring(s):
