def numberOfSubarrays(nums, k):
    def at_most(k):
        left = odds = count = 0
        for right in range(len(nums)):
            if nums[right] % 2 == 1:
                odds += 1
            while odds > k:
                if nums[left] % 2 == 1:
                    odds -= 1
                left += 1
            count += right - left + 1
        return count
    return at_most(k) - at_most(k - 1)

def longestOnes(nums, k):
