def minimumOperations(nums):
    n = len(nums)
    even = Counter(nums[i] for i in range(0, n, 2))
    odd = Counter(nums[i] for i in range(1, n, 2))

    def top2(c):
        items = c.most_common(2)
        if len(items) == 0: return (0, 0, 0)
        if len(items) == 1: return (items[0][0], items[0][1], 0)
        return (items[0][0], items[0][1], items[1][1])

    e_val, e1, e2 = top2(even)
    o_val, o1, o2 = top2(odd)

    if e_val != o_val:
        return n - (e1 + o1)
    return n - max(e1 + o2, e2 + o1)

