def maxTurbulenceSize(arr):
    left = result = 1
    for right in range(1, len(arr)):
        if right == 1:
            if arr[right] != arr[right-1]:
                result = 2
            continue
        c1 = (arr[right-1] > arr[right-2])   # sign of previous comparison
        c2 = (arr[right] > arr[right-1])      # sign of current comparison
        if arr[right-1] == arr[right]:
            left = right  # equal breaks turbulence
        elif c1 == c2:
            left = right - 1  # monotone — shrink
        result = max(result, right - left + 1)
    return result

def maxConsecutiveAnswers(answerKey, k):
    def longest_with_at_most_k_flips(char):
        left = count = result = 0
        for right in range(len(answerKey)):
            if answerKey[right] == char:
                count += 1
            while count > k:
                if answerKey[left] == char:
                    count -= 1
                left += 1
            result = max(result, right - left + 1)
        return result

    return max(longest_with_at_most_k_flips('T'),
               longest_with_at_most_k_flips('F'))

def maxSumOfThreeSubarrays(nums, k):
    n = len(nums)
    sums = [sum(nums[:k])]
    for i in range(k, n):
        sums.append(sums[-1] + nums[i] - nums[i-k])
    left = [0] * n
    best = 0
    for i in range(n - k + 1):
        if sums[i] > sums[best]:
            best = i
        left[i] = best
    right = [0] * n
    best = n - k
    for i in range(n - k, -1, -1):
        if sums[i] >= sums[best]:
            best = i
        right[i] = best
    res = None
    best_sum = 0
    for mid in range(k, n - 2*k + 1):
        l, r = left[mid - k], right[mid + k]
        total = sums[l] + sums[mid] + sums[r]
        if total > best_sum:
            best_sum = total
            res = [l, mid, r]
    return res

def minWindowSubsequence(s1, s2):
    best = ""
    i = 0
    while i < len(s1):
        j = 0
        while i < len(s1) and j < len(s2):
            if s1[i] == s2[j]:
                j += 1
            i += 1
        if j < len(s2):
            break
        end = i
        j -= 1
        i -= 1
        while j >= 0:
            if s1[i] == s2[j]:
                j -= 1
            i -= 1
        i += 1
        window = s1[i:end]
        if not best or len(window) < len(best):
            best = window
        i += 1
    return best

def countSubarrays(nums, minK, maxK):
    res = 0
    bad = min_pos = max_pos = -1
    for i, x in enumerate(nums):
        if x < minK or x > maxK:
            bad = i
        if x == minK:
            min_pos = i
        if x == maxK:
            max_pos = i
        res += max(0, min(min_pos, max_pos) - bad)
    return res

def smallestDistancePair(nums, k):
    nums.sort()
    n = len(nums)

    def count_pairs(mid):
        left = 0
        count = 0
        for right in range(n):
            while nums[right] - nums[left] > mid:
                left += 1
            count += right - left
        return count

    lo, hi = 0, nums[-1] - nums[0]
    while lo < hi:
        m = (lo + hi) // 2
        if count_pairs(m) >= k:
            hi = m
        else:
            lo = m + 1
    return lo

from collections import defaultdict

def smallestRange(nums):
    merged = sorted((x, i) for i, lst in enumerate(nums) for x in lst)
    k = len(nums)
    freq = defaultdict(int)
    have = 0
    left = 0
    res = (merged[0][0], merged[-1][0])
    for right, (val, idx) in enumerate(merged):
        if freq[idx] == 0:
            have += 1
        freq[idx] += 1
        while have == k:
            lo, li = merged[left]
            if val - lo < res[1] - res[0]:
                res = (lo, val)
            freq[li] -= 1
            if freq[li] == 0:
                have -= 1
            left += 1
    return list(res)

def minKBitFlips(nums, k):
    n = len(nums)
    flip = [0] * n
    flipped = 0
    res = 0
    for i in range(n):
        if i >= k:
            flipped ^= flip[i - k]
        if nums[i] ^ flipped == 0:
            if i + k > n:
                return -1
            flip[i] = 1
            flipped ^= 1
            res += 1
    return res

from collections import defaultdict

class FreqStack:
    def __init__(self):
        self.freq = defaultdict(int)
        self.group = defaultdict(list)
        self.max_freq = 0

    def push(self, val):
        self.freq[val] += 1
        f = self.freq[val]
        self.max_freq = max(self.max_freq, f)
        self.group[f].append(val)

    def pop(self):
        val = self.group[self.max_freq].pop()
        self.freq[val] -= 1
        if not self.group[self.max_freq]:
            self.max_freq -= 1
        return val

fs = FreqStack()
for v in [5,7,5,7,4,5]:
    fs.push(v)

def minOperations(nums):
    n = len(nums)
    unique = sorted(set(nums))
    res = n
    j = 0
    for i, x in enumerate(unique):
        while j < len(unique) and unique[j] < x + n:
            j += 1
        res = min(res, n - (j - i))
    return res
